css:
.gh-course-page {
  --gh-green: #8fa78b;
  --gh-green-deep: #748b71;
  --gh-green-pale: #e8eee5;
  --gh-cream: #faf8f1;
  --gh-cream-light: #fcfbf7;
  --gh-white: #ffffff;
  --gh-text: #555d59;
  --gh-line: #d8e0d4;
  color: var(--gh-text);
  font-family: "Zen Maru Gothic", "Hiragino Maru Gothic ProN", "Yu Gothic", Meiryo, sans-serif;
  font-size: 16px;
  line-height: 2;
  letter-spacing: 0.035em;
}

.gh-course-page,
.gh-course-page * {
  box-sizing: border-box;
}

.gh-course-page .gh-inner {
  width: min(100%, 1080px);
  margin: 0 auto;
}

.gh-course-page p {
  margin: 0 0 1.15em;
}

.gh-course-page p:last-child {
  margin-bottom: 0;
}

.gh-course-page a {
  color: inherit;
}

.gh-course-page .gh-hero {
  margin-bottom: 56px;
  padding: 72px 32px;
  text-align: center;
  background: linear-gradient(135deg, var(--gh-cream-light), var(--gh-cream));
  border-top: 3px solid var(--gh-green);
  border-radius: 0 0 26px 26px;
}

.gh-course-page .gh-eyebrow {
  margin: 0 0 12px;
  color: var(--gh-green-deep);
  font-size: 0.96rem;
  font-weight: 500;
  letter-spacing: 0.14em;
}

.gh-course-page .gh-hero-title {
  margin: 0;
  color: var(--gh-text);
  font-size: clamp(1.75rem, 4vw, 2.65rem);
  font-weight: 500;
  line-height: 1.55;
}

.gh-course-page .gh-hero-copy {
  max-width: 820px;
  margin: 28px auto 0;
}

.gh-course-page .gh-hero-lead {
  margin: 0 0 22px;
  color: var(--gh-text);
  font-size: clamp(1.1rem, 2.3vw, 1.35rem);
  font-weight: 500;
  line-height: 1.9;
}

.gh-course-page .gh-hero-text {
  max-width: 780px;
  margin: 0 auto;
  text-align: left;
}

.gh-course-page .gh-section {
  margin: 0 0 64px;
}

.gh-course-page .gh-heading {
  margin: 0 0 30px;
  padding-bottom: 13px;
  color: var(--gh-text);
  font-size: clamp(1.45rem, 3vw, 2rem);
  font-weight: 500;
  text-align: center;
  border-bottom: 1px solid var(--gh-line);
}

.gh-course-page .gh-heading::after {
  display: block;
  width: 80px;
  height: 3px;
  margin: 13px auto -16px;
  background: var(--gh-green);
  content: "";
}

.gh-course-page .gh-subheading {
  margin: 0 0 16px;
  color: var(--gh-text);
  font-size: clamp(1.12rem, 2vw, 1.34rem);
  font-weight: 500;
  line-height: 1.75;
}

.gh-course-page .gh-lead {
  max-width: 860px;
  margin: 0 auto;
  padding: 38px 44px;
  text-align: left;
  background: var(--gh-white);
  border: 1px solid var(--gh-line);
  border-radius: 20px;
}

.gh-course-page .gh-emphasis {
  color: var(--gh-green-deep);
  font-weight: 500;
}

.gh-course-page .gh-check-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px 22px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.gh-course-page .gh-check-list li {
  position: relative;
  padding: 17px 18px 17px 48px;
  background: var(--gh-cream-light);
  border: 1px solid var(--gh-line);
  border-radius: 12px;
}

.gh-course-page .gh-check-list li::before {
  position: absolute;
  top: 17px;
  left: 18px;
  color: var(--gh-green-deep);
  font-weight: 700;
  content: "✓";
}

.gh-course-page .gh-after-list {
  margin: 24px 0 0;
  text-align: center;
}

.gh-course-page .gh-two-grid,
.gh-course-page .gh-support-grid,
.gh-course-page .gh-course-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 22px;
}

.gh-course-page .gh-learning-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 22px;
}

.gh-course-page .gh-card,
.gh-course-page .gh-learning-card,
.gh-course-page .gh-support-card,
.gh-course-page .gh-course-card {
  padding: 30px 26px;
  background: var(--gh-cream-light);
  border: 1px solid var(--gh-line);
  border-radius: 18px;
}

.gh-course-page .gh-card-number {
  display: grid;
  width: 44px;
  height: 44px;
  margin: 0 auto 15px;
  color: #fff;
  font-weight: 500;
  place-items: center;
  background: var(--gh-green);
  border-radius: 50%;
}

.gh-course-page .gh-card-title {
  margin: 0 0 14px;
  color: var(--gh-text);
  font-size: 1.15rem;
  font-weight: 500;
  line-height: 1.7;
  text-align: center;
}

.gh-course-page .gh-learning-card ul {
  margin: 0 0 18px;
  padding-left: 1.25em;
}

.gh-course-page .gh-learning-card li {
  margin-bottom: 8px;
}

.gh-course-page .gh-learning-card li::marker {
  color: var(--gh-green-deep);
}

.gh-course-page .gh-note {
  margin: 20px 0 0;
  font-size: 0.92rem;
  text-align: center;
}

.gh-course-page .gh-message,
.gh-course-page .gh-quote {
  padding: 42px;
  background: var(--gh-cream);
  border-radius: 20px;
}

.gh-course-page .gh-message-copy {
  max-width: 820px;
  margin: 0 auto;
  text-align: left;
}

.gh-course-page .gh-quote-text {
  margin: 0 0 24px;
  color: var(--gh-green-deep);
  font-size: clamp(1.25rem, 2.5vw, 1.65rem);
  font-weight: 500;
  line-height: 1.8;
  text-align: center;
}

.gh-course-page .gh-support-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.gh-course-page .gh-support-card {
  background: var(--gh-white);
  box-shadow: 0 7px 24px rgba(85, 93, 89, 0.07);
}

.gh-course-page .gh-support-icon {
  display: grid;
  width: 48px;
  height: 48px;
  margin: 0 auto 15px;
  place-items: center;
  color: var(--gh-green-deep);
  font-size: 1.2rem;
  font-weight: 500;
  background: var(--gh-green-pale);
  border-radius: 50%;
}

.gh-course-page .gh-course-card {
  position: relative;
  padding-top: 38px;
  background: var(--gh-white);
}

.gh-course-page .gh-course-card.is-primary {
  border: 2px solid var(--gh-green);
}

.gh-course-page .gh-course-label {
  display: inline-block;
  margin: 0 0 14px;
  padding: 4px 13px;
  color: #fff;
  font-size: 0.88rem;
  background: var(--gh-green);
  border-radius: 999px;
}

.gh-course-page .gh-course-title {
  margin: 0 0 16px;
  color: var(--gh-text);
  font-size: clamp(1.18rem, 2.2vw, 1.45rem);
  font-weight: 500;
  line-height: 1.65;
}

.gh-course-page .gh-profile {
  padding: 42px;
  background: var(--gh-cream-light);
  border: 1px solid var(--gh-line);
  border-radius: 20px;
}

.gh-course-page .gh-profile-copy {
  max-width: 820px;
  margin: 0 auto;
  text-align: left;
}

.gh-course-page .gh-button-wrap {
  margin-top: 28px;
  text-align: center;
}

.gh-course-page .gh-cta {
  padding: 54px 30px;
  text-align: center;
  background: var(--gh-green-pale);
  border-radius: 24px;
}

.gh-course-page .gh-cta-title {
  margin: 0 0 14px;
  color: var(--gh-text);
  font-size: clamp(1.45rem, 3vw, 1.9rem);
  font-weight: 500;
  line-height: 1.65;
}

.gh-course-page .gh-cta-copy {
  max-width: 760px;
  margin: 0 auto;
}

.gh-course-page .gh-buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  justify-content: center;
  margin-top: 28px;
}

.gh-course-page .gh-button {
  display: inline-flex;
  min-width: 250px;
  min-height: 58px;
  padding: 12px 28px;
  align-items: center;
  justify-content: center;
  color: #fff !important;
  font-weight: 400;
  line-height: 1.5;
  text-align: center;
  text-decoration: none !important;
  background: var(--gh-green);
  border: 1px solid var(--gh-green);
  border-radius: 6px;
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.gh-course-page .gh-button.is-secondary {
  color: var(--gh-green-deep) !important;
  background: #fff;
}

.gh-course-page .gh-button:hover,
.gh-course-page .gh-button:focus {
  opacity: 0.86;
  transform: translateY(-1px);
}

@media (max-width: 900px) {
  .gh-course-page .gh-learning-grid,
  .gh-course-page .gh-support-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 767px) {
  .gh-course-page {
    font-size: 16px;
  }

  .gh-course-page .gh-hero {
    margin-bottom: 40px;
    padding: 48px 20px;
  }

  .gh-course-page .gh-section {
    margin-bottom: 48px;
  }

  .gh-course-page .gh-lead,
  .gh-course-page .gh-message,
  .gh-course-page .gh-quote,
  .gh-course-page .gh-profile {
    padding: 28px 22px;
  }

  .gh-course-page .gh-check-list,
  .gh-course-page .gh-two-grid,
  .gh-course-page .gh-course-grid {
    grid-template-columns: 1fr;
  }

  .gh-course-page .gh-card,
  .gh-course-page .gh-learning-card,
  .gh-course-page .gh-support-card,
  .gh-course-page .gh-course-card {
    padding: 26px 21px;
  }

  .gh-course-page .gh-cta {
    padding: 42px 20px;
  }

  .gh-course-page .gh-button {
    width: 100%;
    min-width: 0;
  }
}
